import type {
  DependencyInstruction,
  InstructionVariableLink,
} from './instructionDependency';

export interface GraphRevisionInstruction extends DependencyInstruction {
  operation?: string | null;
}

const SHA_256_INITIAL = [
  0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
  0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
] as const;

const SHA_256_ROUND = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5,
  0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
  0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc,
  0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
  0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
  0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3,
  0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5,
  0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
  0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
] as const;

const rotateRight = (value: number, amount: number): number =>
  (value >>> amount) | (value << (32 - amount));

const utf8Bytes = (text: string): number[] => {
  const bytes: number[] = [];
  for (let index = 0; index < text.length; index += 1) {
    let codePoint = text.charCodeAt(index);
    if (codePoint >= 0xd800 && codePoint <= 0xdbff) {
      const low = text.charCodeAt(index + 1);
      if (low >= 0xdc00 && low <= 0xdfff) {
        codePoint = 0x10000 + ((codePoint - 0xd800) << 10) + low - 0xdc00;
        index += 1;
      } else {
        codePoint = 0xfffd;
      }
    } else if (codePoint >= 0xdc00 && codePoint <= 0xdfff) {
      codePoint = 0xfffd;
    }

    if (codePoint <= 0x7f) {
      bytes.push(codePoint);
    } else if (codePoint <= 0x7ff) {
      bytes.push(
        0xc0 | (codePoint >>> 6),
        0x80 | (codePoint & 0x3f),
      );
    } else if (codePoint <= 0xffff) {
      bytes.push(
        0xe0 | (codePoint >>> 12),
        0x80 | ((codePoint >>> 6) & 0x3f),
        0x80 | (codePoint & 0x3f),
      );
    } else {
      bytes.push(
        0xf0 | (codePoint >>> 18),
        0x80 | ((codePoint >>> 12) & 0x3f),
        0x80 | ((codePoint >>> 6) & 0x3f),
        0x80 | (codePoint & 0x3f),
      );
    }
  }
  return bytes;
};

/** Synchronous browser-safe SHA-256 used to match Java MessageDigest output. */
export const sha256Utf8 = (text: string): string => {
  const bytes = utf8Bytes(text);
  const byteLength = bytes.length;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  const bitLength = byteLength * 8;
  const high = Math.floor(bitLength / 0x100000000);
  const low = bitLength >>> 0;
  for (let shift = 24; shift >= 0; shift -= 8) {
    bytes.push((high >>> shift) & 0xff);
  }
  for (let shift = 24; shift >= 0; shift -= 8) {
    bytes.push((low >>> shift) & 0xff);
  }

  const hash: number[] = [...SHA_256_INITIAL];
  const words = new Uint32Array(64);
  for (let offset = 0; offset < bytes.length; offset += 64) {
    for (let index = 0; index < 16; index += 1) {
      const start = offset + index * 4;
      words[index] = (
        (bytes[start] << 24)
        | (bytes[start + 1] << 16)
        | (bytes[start + 2] << 8)
        | bytes[start + 3]
      ) >>> 0;
    }
    for (let index = 16; index < 64; index += 1) {
      const previous15 = words[index - 15];
      const previous2 = words[index - 2];
      const sigma0 = (
        rotateRight(previous15, 7)
        ^ rotateRight(previous15, 18)
        ^ (previous15 >>> 3)
      ) >>> 0;
      const sigma1 = (
        rotateRight(previous2, 17)
        ^ rotateRight(previous2, 19)
        ^ (previous2 >>> 10)
      ) >>> 0;
      words[index] = (
        words[index - 16]
        + sigma0
        + words[index - 7]
        + sigma1
      ) >>> 0;
    }

    let [a, b, c, d, e, f, g, h] = hash;
    for (let index = 0; index < 64; index += 1) {
      const sum1 = (
        rotateRight(e, 6)
        ^ rotateRight(e, 11)
        ^ rotateRight(e, 25)
      ) >>> 0;
      const choose = ((e & f) ^ (~e & g)) >>> 0;
      const first = (h + sum1 + choose + SHA_256_ROUND[index] + words[index]) >>> 0;
      const sum0 = (
        rotateRight(a, 2)
        ^ rotateRight(a, 13)
        ^ rotateRight(a, 22)
      ) >>> 0;
      const majority = ((a & b) ^ (a & c) ^ (b & c)) >>> 0;
      const second = (sum0 + majority) >>> 0;
      h = g;
      g = f;
      f = e;
      e = (d + first) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (first + second) >>> 0;
    }
    hash[0] = (hash[0] + a) >>> 0;
    hash[1] = (hash[1] + b) >>> 0;
    hash[2] = (hash[2] + c) >>> 0;
    hash[3] = (hash[3] + d) >>> 0;
    hash[4] = (hash[4] + e) >>> 0;
    hash[5] = (hash[5] + f) >>> 0;
    hash[6] = (hash[6] + g) >>> 0;
    hash[7] = (hash[7] + h) >>> 0;
  }

  return hash.map(value => value.toString(16).padStart(8, '0')).join('');
};

const javaValue = (value: unknown): string =>
  value == null ? 'null' : String(value);

const nullableNumberOrder = (
  left: number | null | undefined,
  right: number | null | undefined,
): number => {
  if (left == null) return right == null ? 0 : 1;
  if (right == null) return -1;
  return left - right;
};

/**
 * Reproduces InstructionGraphRevisionService exactly. React can therefore
 * prove that its rendered graph is the same graph authorized by Java before
 * projecting FULL or DIRECT Memory List selections.
 */
export const computeInstructionGraphRevision = (
  instructions:
    | readonly (GraphRevisionInstruction | null | undefined)[]
    | null
    | undefined,
  variableLinks:
    | readonly (InstructionVariableLink | null | undefined)[]
    | null
    | undefined,
): string => {
  const canonicalRows = [...(instructions ?? [])]
    .filter((row): row is GraphRevisionInstruction => row != null)
    .sort((left, right) => nullableNumberOrder(left.id, right.id))
    .map(row => [
      row.id,
      row.blockId,
      row.instructionOrderNumber,
      row.actions,
      row.parentId,
      row.parentBlockId,
      row.variableId,
      row.operation,
    ].map(javaValue).join('|') + '\n');

  const canonicalVariables = [...(variableLinks ?? [])]
    .filter((variable): variable is InstructionVariableLink =>
      variable != null && variable.id != null)
    .sort((left, right) =>
      nullableNumberOrder(left.id, right.id)
      || nullableNumberOrder(left.instructionId, right.instructionId))
    .map(variable =>
      `VARIABLE|${javaValue(variable.id)}|${javaValue(variable.instructionId)}\n`);

  return sha256Utf8([...canonicalRows, ...canonicalVariables].join(''));
};
